 "content": "def transform(grid):
    """Fill color 2 inside complete symmetric diagonal chevrons of markers."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}

    # A chevron's apex may point down or up. Both arms must be marked at each
    # step; fill only the strict interior between them.
    for r0, c0 in sorted(markers):
        for direction in (-1, 1):
            max_depth = min(r0 if direction == -1 else h - 1 - r0,
                            c0, w - 1 - c0)
            for depth in range(1, max_depth + 1):
                if not all((r0 + direction * d, c0 - d) in markers and
                           (r0 + direction * d, c0 + d) in markers
                           for d in range(1, depth + 1)):
                    break
                for d in range(1, depth + 1):
                    r = r0 + direction * d
                    for c in range(c0 - d + 1, c0 + d):
                        if grid[r][c] == 0:
                            out[r][c] = 2
    return out
